struct Clip {
    let id: Int
    let seconds: Int
    let selected: Bool
}
func previewSeconds(
    _ clips: [Clip], transform: (Int) -> Int
) -> Int {
    clips.filter { $0.selected }
        .map { transform($0.seconds) }
        .reduce(0, +)
}
func makeCap(limit: Int) -> (Int) -> Int {
    { min(max($0, 0), limit) }
}
let clips = [
    Clip(id: 31, seconds: 40, selected: true),
    Clip(id: 32, seconds: 90, selected: false),
    Clip(id: 33, seconds: 20, selected: true)
]
print(previewSeconds(clips, transform: makeCap(limit: 15)))
print(previewSeconds(clips, transform: makeCap(limit: 30)))

Вывод: 30 и 50. Настройка приходит в функцию значением, режимы не используют общий изменяемый предел.

struct Clip {
    let id: Int
    let seconds: Int
    let selected: Bool
}
func changingSeconds(_ clip: Clip, to seconds: Int) -> Clip {
    Clip(id: clip.id, seconds: max(0, seconds), selected: clip.selected)
}
let old = Clip(id: 31, seconds: 40, selected: true)
let updated = changingSeconds(old, to: -5)
print(old.seconds, updated.seconds, updated.id)

Вывод: 40 0 31. Возвращено новое значение; исходный ролик не изменён.
